CREATE TABLE `nilai_anaks` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tajwid` double DEFAULT NULL,
  `bobot_tajwid` double DEFAULT NULL,
  `lagu` double DEFAULT NULL,
  `bobot_lagu` double DEFAULT NULL,
  `fashahah` double DEFAULT NULL,
  `bobot_fashahah` double DEFAULT NULL,
  `suara` double DEFAULT NULL,
  `total` double DEFAULT NULL,
  `bobot_total` double DEFAULT NULL,
  `final_bobot` double DEFAULT NULL,
  `peserta_id` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `anak_peserta_id` (`peserta_id`),
  CONSTRAINT `anak_peserta_id` FOREIGN KEY (`peserta_id`) REFERENCES `pesertas` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
